<script setup>import {useRouter} from 'vue-router';import {store,saveCart} from '../main';const props=defineProps({product:Object});const router=useRouter();function add(){const x=store.cart.find(i=>i.productId===props.product.id);if(x)x.quantity++;else store.cart.push({productId:props.product.id,name:props.product.name,sku:props.product.sku,price:props.product.price,quantity:1});saveCart();}function open(){router.push(`/product/${props.product.id}`)}</script>
<template><article class="product-card"><button class="product-image" @click="open"><span v-if="product.stock<=0" class="badge muted">OUT OF STOCK</span><div class="device-art">{{product.brand}}</div></button><div class="eyebrow">{{product.brand}}</div><h3>{{product.name}}</h3><p>{{product.attributes?.capacity || product.attributes?.display || product.attributes?.interface || 'Precision engineered'}}</p><div class="card-bottom"><strong>${{product.price.toLocaleString(undefined,{minimumFractionDigits:2})}}</strong><button class="text-button" :disabled="product.stock<=0" @click="add">{{product.stock>0?'Add':'Notify Me'}}</button></div></article></template>
